<?php
declare(strict_types=1);
require_once __DIR__ . '/employee_ui.php'; require_role('employee'); require_permission('view_payslip');
$stmt=db()->prepare('SELECT month_year,working_days,present_days,half_days,paid_leaves,absent_days,payable_days,basic_salary_payable,allowance,deduction,net_salary,payment_status,payment_date FROM salary_payroll WHERE employee_id=? ORDER BY month_year DESC');$stmt->execute([$_SESSION['user']['id']]);$rows=$stmt->fetchAll();function e(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Payslips</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><div class="d-flex justify-content-between"><h1 class="h3">My Payslips</h1><a href="employee_dashboard.php">Dashboard</a></div><div class="card card-body"><table class="table"><thead><tr><th>Month</th><th>Payable days</th><th>Net salary</th><th>Status</th><th>Payment date</th></tr></thead><tbody><?php foreach($rows as $x):?><tr><td><?=e($x['month_year'])?></td><td><?=e((string)$x['payable_days'])?></td><td><?=inr($x['net_salary'])?></td><td><?=e($x['payment_status'])?></td><td><?=e($x['payment_date']??'')?></td></tr><?php endforeach;?></tbody></table></div></main></body></html>
